        posY += shift;
        break;
      case 2:
        posX += shift;
        break;
      case 3:
        posY -= shift;
        break;
      case 4:
        posX -= shift;
        posY -= shift;
        break;
      case 5:
        posX += shift;
        posY -= shift;
        break;
      case 6:
        posX -= shift;
        posY += shift;
        break;
      case 7:
        posX += shift;
        posY += shift;
        break;
      default:
        bError = true;
        break;
