//------------------------------------------------------------------------------
// Address: 0x10147EC0
// Name: private: bool CCoreDispInfo::DoesEdgeExist(int,int,int,int)
// Source: json
//------------------------------------------------------------------------------
bool __thiscall CCoreDispInfo::DoesEdgeExist(
        CCoreDispInfo *this,
        int indexRow,
        int indexCol,
        int direction,
        int postSpacing)
{
  bool result; // al

  switch ( direction )
  {
    case 0:
      result = indexRow - 1 >= 0;
      break;
    case 1:
      result = indexCol + 1 <= postSpacing - 1;
      break;
    case 2:
      result = indexRow + 1 <= postSpacing - 1;
      break;
    case 3:
      result = indexCol - 1 >= 0;
      break;
    default:
      result = false;
      break;
  }
  return result;
}

